import test from 'node:test';
import assert from 'node:assert/strict';
import {selectRecords} from '../src/select.js';
test('public selection contract', () => {
  const a=Object.freeze({id:'a',tenantId:'t1'}), b=Object.freeze({id:'b',tenantId:'t1'}), other=Object.freeze({id:'a',tenantId:'t2'});
  const rows=Object.freeze([b,a,other,a]), ids=Object.freeze(['a','b']);
  assert.deepEqual(selectRecords(rows,'t1',ids),[b,a,a]);
  assert.equal(selectRecords(rows,'t1',['a'])[0],a);
  assert.deepEqual(selectRecords(rows,'t1',[]),[]);
  assert.deepEqual(selectRecords(rows,'t2',['a']),[other]);
  assert.deepEqual(rows,[b,a,other,a]);
  assert.deepEqual(ids,['a','b']);
});

