const rules = {
  tenant: (row, value) => row.tenantId === value,
  selected: (row, value) => value.includes(row.id),
};
export function selectRecords(rows, tenantId, selectedIds) {
  const plan = [{kind: 'tenant', value: tenantId}, {kind: 'selected', value: selectedIds}];
  return rows.filter(row => plan.every(step => rules[step.kind](row, step.value)));
}

